import {copyPractice,TYPE_LABELS,SUBTRACTION_TYPES,validatePractice} from './practice-config.js';
const help=(title,text)=>`<details class="practice-help"><summary aria-label="Help: ${title}">? ${title}</summary><p>${text}</p></details>`;
export function practiceSettingsMarkup(value){const c=copyPractice(value);return `<fieldset class="practice-settings"><legend>Math practice</legend>${help('Subjects and new runs','Choose Time, Subtraction, or both. Changes apply to new stage runs and new Practice Relays. Continue keeps its saved questions. Restart a stage to use the new settings; its gate work restarts, but earned powers and reports stay.')}<label><input type="checkbox" id="math-time" ${c.subjects.includes('time')?'checked':''}> Time</label><label><input type="checkbox" id="math-subtraction" ${c.subjects.includes('subtraction')?'checked':''}> Subtraction: missing numbers</label><div id="subtraction-options" ${c.subjects.includes('subtraction')?'':'hidden'}>${help('Question types','The starting number is the minuend: □ − 7 = 12. The amount taken away is the subtrahend: 19 − □ = 12. Choose equations, word problems, or both. Types are shuffled across gates, with balanced coverage when enough questions are available.')} ${SUBTRACTION_TYPES.map(t=>`<label><input type="checkbox" data-math-type="${t}" ${c.subtraction.types.includes(t)?'checked':''}> ${TYPE_LABELS[t]}</label>`).join('')}<label>Number range<select id="math-maximum">${[20,100,1000].map(n=>`<option value="${n}" ${c.subtraction.maximum===n?'selected':''}>Within ${n.toLocaleString('en-US')}</option>`).join('')}</select></label><label><input type="checkbox" id="math-zero" ${c.subtraction.includeZero?'checked':''}> Include zero</label>${help('Range and zero','Every value, including the missing answer, stays within the selected maximum. With zero off, every value is positive. With zero on, occasional problems include zero.')}</div></fieldset>`;}
export function bindPracticeSettings(overlay){overlay.querySelector('#math-subtraction')?.addEventListener('change',e=>{overlay.querySelector('#subtraction-options').hidden=!e.currentTarget.checked;if(e.currentTarget.checked&&![...overlay.querySelectorAll('[data-math-type]')].some(n=>n.checked))overlay.querySelectorAll('[data-math-type]').forEach(n=>n.checked=true);});}
export function readPracticeSettings(overlay){const c={subjects:['time','subtraction'].filter(s=>overlay.querySelector('#math-'+s).checked),subtraction:{types:[...overlay.querySelectorAll('[data-math-type]')].filter(n=>n.checked).map(n=>n.dataset.mathType),maximum:Number(overlay.querySelector('#math-maximum').value),includeZero:overlay.querySelector('#math-zero').checked}};const error=validatePractice(c);if(error)throw Error(error);return copyPractice(c);}
